const APP_VERSION="6.1.2";const APP_NAME="Catalogue";function parseVersion(v){const parts=String(v||"").trim().replace(/^v/i,"").split(".").map(n=>parseInt(n,10)||0);while(parts.length<3)parts.push(0);return[parts[0],parts[1],parts[2]]}function compareVersions(a,b){const[ma,na,pa]=parseVersion(a);const[mb,nb,pb]=parseVersion(b);if(ma!==mb)return ma-mb;if(na!==nb)return na-nb;return pa-pb}function bumpPatch(v=APP_VERSION){const[m,n,p]=parseVersion(v);return`${m}.${n}.${p+1}`}function bumpMinor(v=APP_VERSION){const[m,n]=parseVersion(v);return`${m}.${n+1}.0`}function bumpMajor(v=APP_VERSION){const[m]=parseVersion(v);return`${m+1}.0.0`}if(typeof self!=="undefined"){self.APP_VERSION=APP_VERSION;self.APP_NAME=APP_NAME}if(typeof window!=="undefined"){window.APP_VERSION=APP_VERSION;window.APP_NAME=APP_NAME}if(typeof module!=="undefined"&&module.exports){module.exports={APP_VERSION:APP_VERSION,APP_NAME:APP_NAME,parseVersion:parseVersion,compareVersions:compareVersions,bumpPatch:bumpPatch,bumpMinor:bumpMinor,bumpMajor:bumpMajor}}